import json
import urllib.request
import concurrent.futures

with open('canais_diretos_multiserver.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

tasks = []
for cat, chs in data.items():
    for ch_name, ch_obj in chs.items():
        for s in ch_obj.get('sources', []):
            tasks.append((cat, ch_name, s.get('name'), s.get('url')))

def test_url(item):
    cat, ch_name, s_name, url = item
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0', 'Origin': 'https://tvzinhaonline.pages.dev'})
    try:
        with urllib.request.urlopen(req, timeout=5) as res:
            if res.status == 200:
                body = res.read(128).decode('utf-8', errors='ignore')
                if '#EXTM3U' in body:
                    return (True, item, 'OK')
                else:
                    return (False, item, 'Not EXTM3U')
            else:
                return (False, item, f'HTTP {res.status}')
    except Exception as e:
        return (False, item, str(e))

total = len(tasks)
online = 0
offline = []

print(f'Starting smoke test of {total} stream endpoints...')
with concurrent.futures.ThreadPoolExecutor(max_workers=20) as executor:
    results = list(executor.map(test_url, tasks))

for success, item, msg in results:
    cat, ch_name, s_name, url = item
    if success:
        online += 1
    else:
        offline.append((cat, ch_name, s_name, msg))

pct = (online / total) * 100
print(f'\n--- Smoke Test Results ---')
print(f'Total endpoints: {total}')
print(f'Online (200 + EXTM3U): {online} ({pct:.1f}%)')
print(f'Offline / Failed: {len(offline)}')

if offline:
    print('\nFailed endpoints:')
    for cat, ch_name, s_name, msg in offline[:15]:
        print(f'  - [{cat}] {ch_name} ({s_name}): {msg}')
"

