        sources = ch_obj.get('sources', [])
        if sources:
            channels.append((cat, ch_name, sources[0]['url']))

def test_channel_segment(item):
    cat, name, m3u8_url = item
    req = urllib.request.Request(m3u8_url, headers={'User-Agent': 'Mozilla/5.0', 'Origin': 'https://tvzinhaonline.pages.dev'})
    try:
        with urllib.request.urlopen(req, timeout=5) as res:
            body = res.read().decode('utf-8', errors='ignore')
            segs = [l for l in body.splitlines() if not l.startswith('#') and l.strip()]
            if not segs:
                return (name, cat, False, 'No segments in manifest')
            seg_url = segs[-1]
            s_req = urllib.request.Request(seg_url, headers={'User-Agent': 'Mozilla/5.0', 'Origin': 'https://tvzinhaonline.pages.dev'})
            with urllib.request.urlopen(s_req, timeout=5) as s_res:
                chunk = s_res.read(188)
                if chunk and chunk[0] == 0x47:
                    return (name, cat, True, 'OK (Valid MPEG-TS)')
                else:
                    return (name, cat, False, 'Invalid TS sync byte')
    except Exception as e:
        return (name, cat, False, str(e))

print(f'Running deep segment validation for {len(channels)} unique channels...')
with concurrent.futures.ThreadPoolExecutor(max_workers=15) as ex:
    results = list(ex.map(test_channel_segment, channels))

working = [r for r in results if r[2]]
failed = [r for r in results if not r[2]]

print(f'\n--- Segment Validation Summary ---')
print(f'Total Channels Tested: {len(channels)}')
print(f'Working Live Video Segments: {len(working)} ({(len(working)/len(channels))*100:.1f}%)')
print(f'Failed Channels: {len(failed)}')

if failed:
    print('\nChannels with Broken Segments:')
    for name, cat, _, reason in failed:
        print(f'  - [{cat}] {name}: {reason}')
"

