import json

with open('data/canais.json', 'r', encoding='utf-8') as f:
    legacy = json.load(f)

with open('canais_diretos_multiserver.json', 'r', encoding='utf-8') as f:
    multiserver = json.load(f)

merged = {}

for cat, chs in multiserver.items():
    merged[cat] = {}
    for ch_name, ch_obj in chs.items():
        # Get legacy contingency players if any
        contingency = []
        if cat in legacy and ch_name in legacy[cat]:
            leg_players = legacy[cat][ch_name]
            for p_name, p_url in leg_players.items():
                contingency.append({
                    'name': f'Contingência ({p_name})',
                    'url': p_url,
                    'type': 'iframe'
                })
        else:
            # Try finding in other categories in legacy
            for l_cat in legacy:
                if ch_name in legacy[l_cat]:
                    for p_name, p_url in legacy[l_cat][ch_name].items():
                        contingency.append({
                            'name': f'Contingência ({p_name})',
                            'url': p_url,
                            'type': 'iframe'
                        })
                    break

        native_sources = []
        for s in ch_obj.get('sources', []):
            native_sources.append({
                'name': s.get('name'),
                'url': s.get('url'),
                'slug': s.get('slug'),
                'cdn': s.get('cdn'),
                'type': 'native'
            })

        merged[cat][ch_name] = {
            'status': ch_obj.get('status', 'ONLINE'),
            'sources': native_sources,
            'contingency': contingency
        }

print('Merged sample channel (Globo):')
print(json.dumps(merged['TV Aberta']['Globo'], indent=2, ensure_ascii=False))
print('\nMerged sample channel (Discovery Channel):')
print(json.dumps(merged['Documentários & Variedades']['Discovery Channel'], indent=2, ensure_ascii=False))
"

