/* Custom "AO VIVO" Live-Edge Sync Button */
.art-live-badge-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 28px;
    padding: 0 10px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    background: rgba(0, 0, 0, 0.55);
    color: #ffffff;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.04em;
    cursor: pointer;
    transition: all 0.2s ease;
    user-select: none;
    margin-right: 6px;
}

.art-live-badge-btn.is-live {
    background: rgba(220, 38, 38, 0.22);
    border-color: rgba(239, 68, 68, 0.65);
    color: #fca5a5;
}

.art-live-badge-btn.is-behind {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.2);
    color: #d4d4d8;
}

.art-live-badge-btn:hover {
    background: rgba(255, 255, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.35);
    transform: translateY(-1px);
}

.art-live-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: #ef4444;
    box-shadow: 0 0 8px #ef4444;
    animation: livePulseAnim 1.6s infinite ease-in-out;
}

.art-live-dot-gray {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: #a1a1aa;
}

@keyframes livePulseAnim {
    0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
    70% { transform: scale(1.15); box-shadow: 0 0 0 6px rgba(239, 68, 68, 0); }
    100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

/* TV Direct Stream Error Overlay */
.channel-direct-error-overlay {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    width: 100%;
    color: #a1a1aa;
    padding: 32px 20px;
    text-align: center;
    background: radial-gradient(circle at center, rgba(30, 41, 59, 0.5) 0%, rgba(10, 12, 16, 0.98) 100%);
    box-sizing: border-box;
    z-index: 20;
}

.channel-direct-error-overlay .error-overlay-title {
    font-size: 17px;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 8px;
}

.channel-direct-error-overlay .error-overlay-desc {
    font-size: 13.5px;
    max-width: 440px;
