import os
import sys

def main():
    with open("script.js", "r", encoding="utf-8") as f:
        lines = f.readlines()

    print(f"Total lines: {len(lines)}")

    # Check delimiters
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}

    in_str = None
    esc = False
    in_line_comment = False
    in_block_comment = False

    for line_idx, line in enumerate(lines, 1):
        i = 0
        in_line_comment = False
        while i < len(line):
            ch = line[i]

            if in_line_comment:
                break

            if in_block_comment:
                if ch == '*' and i + 1 < len(line) and line[i+1] == '/':
                    in_block_comment = False
                    i += 2
                    continue
                i += 1
                continue

            if in_str:
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == in_str:
                    in_str = None
                i += 1
                continue

            if ch in ('"', "'", '`'):
                in_str = ch
                i += 1
                continue

            if ch == '/' and i + 1 < len(line):
                if line[i+1] == '/':
                    in_line_comment = True
                    break
                elif line[i+1] == '*':
                    in_block_comment = True
                    i += 2
                    continue

            if ch in ('(', '{', '['):
                stack.append((ch, line_idx, i + 1))
            elif ch in (')', '}', ']'):
                if not stack:
                    print(f"ERROR: Unmatched closing '{ch}' at line {line_idx}:{i+1}")
                    return
                top, l_idx, col = stack.pop()
                if top != pairs[ch]:
                    print(f"ERROR: Mismatched '{top}' (from line {l_idx}:{col}) with '{ch}' at line {line_idx}:{i+1}")
                    return
            i += 1

    if stack:
        print(f"ERROR: {len(stack)} unclosed delimiters! First unclosed: {stack[0]}")
    else:
        print("SUCCESS: All brackets, braces, and parentheses are perfectly balanced!")

if __name__ == "__main__":
    main()

