/**
 * TVZINHA ONLINE - Dynamic Multi-Team Upcoming Matches Module (Sports)
 * Fetches and renders match schedule feeds with team crest resolution and custom team picker
 */

import { store } from '../core/state.js';
import { FAVORITE_TEAM_KEY, KNOWN_TEAM_CRESTS, GITHUB_RAW_FEED_URL } from '../core/constants.js';
import { getUiSvg } from '../core/icons.js';
import { showToast } from '../core/toast.js';

let matchesRefreshTimer = null;

export function resolveClientTeamCrest(teamId, teamInfo) {
    if (teamInfo && teamInfo.escudo && teamInfo.escudo.startsWith("http")) {
        return teamInfo.escudo;
    }
    const matches = (teamInfo && teamInfo.matches) || [];
    const targetName = ((teamInfo && teamInfo.name) || teamId).toLowerCase();
    for (const m of matches) {
        const mName = (m.mandante?.nome || "").toLowerCase();
        if ((mName.includes(targetName) || targetName.includes(mName)) && m.mandante?.escudo) {
            return m.mandante.escudo;
        }
        const vName = (m.visitante?.nome || "").toLowerCase();
        if ((vName.includes(targetName) || targetName.includes(vName)) && m.visitante?.escudo) {
            return m.visitante.escudo;
        }
    }
    return KNOWN_TEAM_CRESTS[teamId] || KNOWN_TEAM_CRESTS["brasil"];
}

export function getFavoriteTeam() {
    return store.favoriteTeam || "vasco";
}

export function setFavoriteTeam(teamId) {
    store.setFavoriteTeam(teamId);
}

export async function fetchUpcomingMatches() {
    if (store.cachedScheduleFeed) {
        return store.cachedScheduleFeed;
    }

    try {
        const remoteUrl = `${GITHUB_RAW_FEED_URL}?t=${Date.now()}`;
        const response = await fetch(remoteUrl, { cache: "no-store" });
        if (response.ok) {
            const data = await response.json();
            if (data && (data.vasco || data.times)) {
                store.setCachedScheduleFeed(data);
                return data;
            }
        }
    } catch (e) {
        console.warn("[MatchesFeed] Aviso ao buscar feed do GitHub:", e);
    }

    try {
        const response = await fetch("data/proximos_jogos.json?t=" + Date.now(), { cache: "no-store" });
        if (response.ok) {
            const data = await response.json();
            store.setCachedScheduleFeed(data);
            return data;
        }
    } catch (e) {
        console.warn("[MatchesFeed] Erro ao carregar feed local de jogos:", e);
    }

    return null;
}

export function getTeamScheduleData(feed, teamId) {
    if (!feed) return null;
    if (feed.times && feed.times[teamId]) {
        return feed.times[teamId];
    }
    if (teamId === "vasco" && feed.vasco) {
        return {
            name: "Vasco da Gama",
            escudo: KNOWN_TEAM_CRESTS["vasco"],
            matches: feed.vasco
        };
    }
    if (feed[teamId] && Array.isArray(feed[teamId])) {
        return {
            name: teamId.charAt(0).toUpperCase() + teamId.slice(1),
            escudo: KNOWN_TEAM_CRESTS[teamId] || KNOWN_TEAM_CRESTS["brasil"],
            matches: feed[teamId]
        };
    }
    return null;
}

export function setupTeamSelectModal(feed) {
    const modal = document.getElementById("team-select-modal");
    if (!modal) return;

    const listEl = document.getElementById("team-select-list");
    const btnClose = document.getElementById("btn-close-team-modal");

    if (listEl && feed) {
        listEl.innerHTML = "";
        const teamsMap = feed.times || {};
        const availableTeams = Object.keys(teamsMap).length > 0
            ? Object.keys(teamsMap)
            : Object.keys(KNOWN_TEAM_CRESTS);

        availableTeams.forEach(teamId => {
            const teamInfo = teamsMap[teamId] || { name: teamId.charAt(0).toUpperCase() + teamId.slice(1) };
            const crestUrl = resolveClientTeamCrest(teamId, teamInfo);
            const isCurrent = teamId === getFavoriteTeam();

            const btn = document.createElement("button");
            btn.className = `team-select-option ${isCurrent ? "active" : ""}`;
            btn.innerHTML = `
                <img src="${crestUrl}" alt="${teamInfo.name}" class="team-option-crest" loading="lazy" onerror="this.src='${KNOWN_TEAM_CRESTS['brasil']}'">
                <span class="team-option-name">${teamInfo.name}</span>
                ${isCurrent ? `<span class="team-option-check">${getUiSvg('check', 14)}</span>` : ""}
            `;
            btn.addEventListener("click", () => {
                setFavoriteTeam(teamId);
                closeTeamSelectModal();
                renderMatchesSection();
                showToast(`Time alterado para ${teamInfo.name}`);
            });
            listEl.appendChild(btn);
        });
    }

    if (btnClose) {
        btnClose.onclick = closeTeamSelectModal;
    }
    modal.onclick = (e) => {
        if (e.target === modal) closeTeamSelectModal();
    };
}

export function openTeamSelectModal() {
    const modal = document.getElementById("team-select-modal");
    if (modal) {
        modal.classList.remove("hidden");
        document.body.style.overflow = "hidden";
    }
}

export function closeTeamSelectModal() {
    const modal = document.getElementById("team-select-modal");
    if (modal) {
        modal.classList.add("hidden");
        document.body.style.overflow = "";
    }
}

export async function renderMatchesSection() {
    const container = document.getElementById("vasco-matches-section");
    if (!container) return;

    const feed = await fetchUpcomingMatches();
    if (!feed) {
        container.style.display = "none";
        return;
    }
    container.style.display = "";

    const currentTeamId = getFavoriteTeam();
    const teamData = getTeamScheduleData(feed, currentTeamId);
    if (!teamData || !teamData.matches || teamData.matches.length === 0) {
        container.style.display = "none";
        return;
    }

    setupTeamSelectModal(feed);

    // Update section title & badge
    const badgeEl = document.getElementById("matches-team-badge");
    const titleEl = document.getElementById("matches-section-title");
    const hintEl = document.getElementById("matches-section-hint");
    const btnChangeLabel = document.getElementById("btn-change-team-label");

    if (badgeEl) {
        const teamCrest = resolveClientTeamCrest(currentTeamId, teamData);
        badgeEl.innerHTML = `<img src="${teamCrest}" alt="${teamData.name}" class="matches-header-crest" onerror="this.src='${KNOWN_TEAM_CRESTS['brasil']}'">`;
    }
    if (titleEl) titleEl.textContent = `Próximos Jogos - ${teamData.name}`;
    if (hintEl) hintEl.textContent = `Agenda atualizada do ${teamData.name} (via ge.globo)`;
    if (btnChangeLabel) btnChangeLabel.textContent = "Trocar Time";

    const btnChange = document.getElementById("btn-change-team");
    if (btnChange) {
        btnChange.onclick = openTeamSelectModal;
    }

    // Render matches cards inside carousel
    const gridEl = document.getElementById("vasco-matches-grid");
    if (!gridEl) return;
    gridEl.innerHTML = "";

    teamData.matches.forEach(match => {
        const card = document.createElement("div");
        card.className = "match-card";
        card.tabIndex = 0;

        const mandanteNome = match.mandante?.nome || "Mandante";
        const visitanteNome = match.visitante?.nome || "Visitante";
        const mandanteEscudo = match.mandante?.escudo || KNOWN_TEAM_CRESTS["brasil"];
        const visitanteEscudo = match.visitante?.escudo || KNOWN_TEAM_CRESTS["brasil"];

        let broadcastHtml = "";
        if (match.transmissao && match.transmissao.length > 0) {
            broadcastHtml = match.transmissao.map(src => {
                return `<button type="button" class="broadcast-pill playable" data-broadcast-name="${src}" title="Buscar canal para ${src}">▶ ${src}</button>`;
            }).join("");
        } else {
            broadcastHtml = `<span class="broadcast-pill empty">Transmissão a confirmar</span>`;
        }

        card.innerHTML = `
            <div class="match-card-header">
                <span class="match-championship">${match.campeonato || "Futebol"}</span>
                <span class="match-round">${match.rodada || ""}</span>
            </div>
            <div class="match-duel">
                <div class="match-team">
                    <img src="${mandanteEscudo}" alt="${mandanteNome}" class="match-team-crest" loading="lazy" onerror="this.src='${KNOWN_TEAM_CRESTS['brasil']}'">
                    <span class="match-team-name">${mandanteNome}</span>
                </div>
                <div class="match-vs">VS</div>
                <div class="match-team">
                    <img src="${visitanteEscudo}" alt="${visitanteNome}" class="match-team-crest" loading="lazy" onerror="this.src='${KNOWN_TEAM_CRESTS['brasil']}'">
                    <span class="match-team-name">${visitanteNome}</span>
                </div>
            </div>
            <div class="match-footer">
                <div class="match-datetime">
                    <span>${match.data_formatada || match.data || ""}</span>
                    ${match.horario ? `<span>• ${match.horario}</span>` : ""}
                </div>
                <div class="match-broadcasts">
                    ${broadcastHtml}
                </div>
            </div>
        `;

        gridEl.appendChild(card);
    });

    setupMatchesCarouselControls(gridEl);
}

function setupMatchesCarouselControls(gridEl) {
    const btnPrev = document.getElementById("btn-matches-prev");
    const btnNext = document.getElementById("btn-matches-next");

    function updateArrows() {
        if (!gridEl) return;
        const maxScroll = gridEl.scrollWidth - gridEl.clientWidth;
        if (btnPrev) btnPrev.disabled = gridEl.scrollLeft <= 5;
        if (btnNext) btnNext.disabled = gridEl.scrollLeft >= maxScroll - 5;
    }

    if (btnPrev) {
        btnPrev.onclick = () => {
            gridEl.scrollBy({ left: -320, behavior: 'smooth' });
        };
    }
    if (btnNext) {
        btnNext.onclick = () => {
            gridEl.scrollBy({ left: 320, behavior: 'smooth' });
        };
    }

    gridEl.addEventListener("scroll", updateArrows, { passive: true });
    updateArrows();

    // Event Delegation: Forward broadcast pill clicks via Store Event
    gridEl.addEventListener("click", (e) => {
        const pill = e.target.closest(".broadcast-pill.playable");
        if (pill) {
            e.preventDefault();
            e.stopPropagation();
            const broadcastName = pill.getAttribute("data-broadcast-name") || "";
            // Dispatch decoupled request to Store
            store.setCurrentView('tv');
            store.dispatchEvent(new CustomEvent('channel:request', {
                detail: {
                    category: "Esportes",
                    channelName: broadcastName
                }
            }));
            showToast(`Buscando canal para ${broadcastName}...`);
        }
    });
}

/**
 * TVZINHA ONLINE - Channels Catalog & TV Interface Module
 * Handles channel data fetching, category filtering, search, and TV player shell controls
 */

import { store } from '../core/state.js';
import { FALLBACK_CHANNELS } from '../core/fallbackChannels.js';
import { getUiSvg, createLogoBadgeHtml } from '../core/icons.js';
import { showToast } from '../core/toast.js';
import { mountTvDirectStream, mountTvContingencyIframe, atomicTvPlayerReset, handleAllDirectSourcesFailed } from '../player/engine.js';

export function normalizeChannelData(raw) {
    if (!raw) return { sources: [], contingency: {} };
    if (raw.sources && Array.isArray(raw.sources)) {
        return {
            status: raw.status || 'ONLINE',
            sources: raw.sources,
            contingency: raw.contingency || {}
        };
    }
    const players = raw.players || raw;
    const contingency = {};
    if (typeof players === 'object') {
        for (const [key, url] of Object.entries(players)) {
            if (typeof url === 'string') {
                contingency[key] = url;
            }
        }
    }
    return {
        status: raw.status || 'ONLINE',
        sources: [],
        contingency
    };
}

export async function initChannelsCatalog() {
    let loadedData = null;
    try {
        const response = await fetch("data/canais.json?v=" + Date.now(), { cache: "no-store" });
        if (response.ok) {
            loadedData = await response.json();
            console.log("[Channels] Catálogo carregado via canais.json");
        }
    } catch (e) {
        console.warn("[Channels] Erro ao carregar data/canais.json, usando dataset de contingência:", e);
    }

    if (!loadedData || Object.keys(loadedData).length === 0) {
        loadedData = FALLBACK_CHANNELS;
        console.log("[Channels] Utilizando FALLBACK_CHANNELS.");
    }

    store.setChannelsData(loadedData);
    buildCategoryPills();
    renderChannels();
    setupSearchHandlers();
    setupSidebarResizer();

    // Listen for channel requests from other modules (e.g. sports matches)
    store.on('channel:request', ({ category, channelName }) => {
        selectChannelByName(category, channelName);
    });

    store.on('favorites:change', () => {
        renderChannels();
    });
}

export function buildCategoryPills() {
    const filterPillsEl = document.getElementById("filter-pills");
    if (!filterPillsEl) return;
    filterPillsEl.innerHTML = "";

    const channelsData = store.channelsData;

    // AdBlock disclaimer pill
    const adblockBtn = document.createElement("button");
    adblockBtn.className = "pill pill-adblock";
    adblockBtn.id = "btn-sidebar-adblock";
    adblockBtn.title = "Como bloquear anúncios e pop-ups dos players";
    adblockBtn.innerHTML = `
        <svg class="icon-svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path>
            <polyline points="9 12 11 14 15 10"></polyline>
        </svg>
        Sem Anúncios
    `;
    filterPillsEl.appendChild(adblockBtn);

    // All pill
    const allBtn = document.createElement("button");
    allBtn.className = `pill ${store.activeFilter === "all" ? "active" : ""}`;
    allBtn.dataset.category = "all";
    allBtn.textContent = "Todos";
    allBtn.onclick = () => setCategoryFilter("all");
    filterPillsEl.appendChild(allBtn);

    // Favorites pill
    const favsBtn = document.createElement("button");
    favsBtn.className = `pill ${store.activeFilter === "favs" ? "active" : ""}`;
    favsBtn.dataset.category = "favs";
    favsBtn.innerHTML = `${getUiSvg('star', 13)} Favoritos`;
    favsBtn.onclick = () => setCategoryFilter("favs");
    filterPillsEl.appendChild(favsBtn);

    // Dynamic Categories
    Object.keys(channelsData).forEach(category => {
        const pill = document.createElement("button");
        pill.className = `pill ${store.activeFilter === category ? "active" : ""}`;
        pill.dataset.category = category;
        pill.textContent = category;
        pill.onclick = () => setCategoryFilter(category);
        filterPillsEl.appendChild(pill);
    });
}

export function setCategoryFilter(category) {
    store.setActiveFilter(category);
    const filterPillsEl = document.getElementById("filter-pills");
    if (!filterPillsEl) return;
    const pills = filterPillsEl.querySelectorAll(".pill");
    pills.forEach(pill => {
        const cat = pill.getAttribute("data-category") || "";
        if (cat === category) pill.classList.add("active");
        else pill.classList.remove("active");
    });
    renderChannels();
}

export function setupSearchHandlers() {
    const searchInput = document.getElementById("search-input");
    const btnClearSearch = document.getElementById("btn-clear-search");

    if (searchInput) {
        searchInput.addEventListener("input", (e) => {
            store.setSearchQuery(e.target.value);
            if (btnClearSearch) {
                if (e.target.value.length > 0) btnClearSearch.classList.remove("hidden");
                else btnClearSearch.classList.add("hidden");
            }
            renderChannels();
        });
    }

    if (btnClearSearch && searchInput) {
        btnClearSearch.onclick = () => {
            searchInput.value = "";
            store.setSearchQuery("");
            btnClearSearch.classList.add("hidden");
            renderChannels();
            searchInput.focus();
        };
    }
}

export function renderChannels() {
    const channelsListEl = document.getElementById("channels-list");
    if (!channelsListEl) return;

    channelsListEl.innerHTML = "";
    const channelsData = store.channelsData;
    const activeFilter = store.activeFilter;
    const searchQuery = store.searchQuery;
    const favorites = store.favorites;

    let hasMatches = false;

    Object.keys(channelsData).forEach(category => {
        if (activeFilter !== "all" && activeFilter !== "favs" && activeFilter !== category) {
            return;
        }

        const categoryChannels = channelsData[category];
        const matchingChannels = Object.keys(categoryChannels).filter(channelName => {
            const matchesSearch = channelName.toLowerCase().includes(searchQuery);
            const matchesFav = activeFilter === "favs" ? favorites.has(channelName) : true;
            return matchesSearch && matchesFav;
        });

        if (matchingChannels.length === 0) return;
        hasMatches = true;

        const groupEl = document.createElement("div");
        groupEl.className = "category-group";

        const iconType = category.toLowerCase().includes("esporte") ? "sports" :
            (category.toLowerCase().includes("notícia") ? "news" :
                (category.toLowerCase().includes("infantil") ? "kids" : "tv"));

        groupEl.innerHTML = `
            <div class="category-header">
                ${getUiSvg(iconType, 16)}
                <span>${category}</span>
                <span class="category-count">(${matchingChannels.length})</span>
            </div>
            <div class="channels-items"></div>
        `;

        const itemsEl = groupEl.querySelector(".channels-items");
        matchingChannels.forEach(channelName => {
            const channelRawData = categoryChannels[channelName];
            const isFav = favorites.has(channelName);

            const itemEl = document.createElement("div");
            itemEl.className = `channel-item ${store.activeChannel && store.activeChannel.name === channelName ? 'active' : ''}`;
            itemEl.dataset.channel = channelName;
            itemEl.dataset.category = category;

            itemEl.innerHTML = `
                <div class="channel-info-wrapper">
                    ${createLogoBadgeHtml(channelName, 'sm')}
                    <div class="channel-text">
                        <span class="channel-name">${channelName}</span>
                    </div>
                </div>
                <button type="button" class="btn-fav-toggle ${isFav ? 'active' : ''}" title="${isFav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}" aria-label="Favoritar ${channelName}">
                    ${isFav ? getUiSvg('starFilled', 15) : getUiSvg('star', 15)}
                </button>
            `;

            // Channel selection on item click
            itemEl.addEventListener("click", (e) => {
                if (e.target.closest(".btn-fav-toggle")) return;
                selectChannel(category, channelName, channelRawData);
            });

            // Fav toggle
            const btnFav = itemEl.querySelector(".btn-fav-toggle");
            if (btnFav) {
                btnFav.onclick = (e) => {
                    e.stopPropagation();
                    store.toggleFavorite(channelName);
                };
            }

            itemsEl.appendChild(itemEl);
        });

        channelsListEl.appendChild(groupEl);
    });

    if (!hasMatches) {
        channelsListEl.innerHTML = `
            <div class="empty-state">
                ${getUiSvg('search', 32)}
                <p>Nenhum canal encontrado.</p>
            </div>
        `;
    }
}

export function selectChannelByName(category, channelName) {
    const channelsData = store.channelsData;
    let targetCat = category;
    let targetData = channelsData[targetCat]?.[channelName];

    if (!targetData) {
        // Fallback search across all categories
        for (const [cat, chs] of Object.entries(channelsData)) {
            if (chs[channelName]) {
                targetCat = cat;
                targetData = chs[channelName];
                break;
            }
            // Fuzzy search by substring
            const fuzzyKey = Object.keys(chs).find(k => k.toLowerCase().includes(channelName.toLowerCase()) || channelName.toLowerCase().includes(k.toLowerCase()));
            if (fuzzyKey) {
                targetCat = cat;
                targetData = chs[fuzzyKey];
                channelName = fuzzyKey;
                break;
            }
        }
    }

    if (targetData) {
        selectChannel(targetCat, channelName, targetData);
    } else {
        showToast(`Canal ${channelName} indisponível no momento.`);
    }
}

export function selectChannel(category, channelName, rawChannelData, preferredOption = null) {
    const data = normalizeChannelData(rawChannelData);
    const hasSources = data.sources && data.sources.length > 0;
    const hasContingency = data.contingency && Object.keys(data.contingency).length > 0;

    if (!hasSources && !hasContingency) {
        showToast(`Canal ${channelName} sem servidores cadastrados.`);
        return;
    }

    store.setCurrentView('tv');

    let selectedServerType = 'direct';
    let selectedSourceIndex = 0;
    let selectedContingencyUrl = '';

    if (hasSources) {
        selectedServerType = 'direct';
        selectedSourceIndex = 0;
    } else {
        selectedServerType = 'contingency';
        const contingencyKeys = Object.keys(data.contingency);
        selectedContingencyUrl = data.contingency[contingencyKeys[0]];
    }

    const channelObj = {
        category,
        name: channelName,
        data,
        serverType: selectedServerType,
        sourceIndex: selectedSourceIndex,
        contingencyUrl: selectedContingencyUrl
    };

    store.setActiveChannel(channelObj);
    renderTvPlayerView(channelObj);
}

