        data.sources.forEach((src, idx) => {
            const isActive = activeChannel.serverType === 'direct' && activeChannel.sourceIndex === idx;
            directServersHtml += `
                <button type="button" class="btn-server-option ${isActive ? 'active' : ''}" data-server-type="direct" data-source-index="${idx}">
                    <span class="server-dot"></span>
                    <span class="server-label">${src.name}</span>
                    ${src.cdn ? `<span class="server-badge">${src.cdn}</span>` : ''}
