    if (hasContingency) {
        Object.entries(data.contingency).forEach(([name, url]) => {
            const isActive = activeChannel.serverType === 'contingency' && activeChannel.contingencyUrl === url;
            contingencyServersHtml += `
                <button type="button" class="btn-server-option ${isActive ? 'active' : ''}" data-server-type="contingency" data-contingency-url="${url}">
                    <span class="server-dot"></span>
