                        <h2 class="current-channel-title">${activeChannel.name}</h2>
                        <span class="current-channel-category">${activeChannel.category}</span>
                    </div>
                    <button type="button" class="btn-fav-current ${isFav ? 'active' : ''}" id="btn-fav-current" title="Favoritar canal">
                        ${isFav ? getUiSvg('starFilled', 16) : getUiSvg('star', 16)}
                    </button>
                </div>
                <div class="playback-bar-actions">
                    <button type="button" class="btn-player-action" id="btn-reload-player" title="Recarregar player">
                        ${getUiSvg('swap', 15)} Recarregar
                    </button>
                    <button type="button" class="btn-player-action" id="btn-fullscreen-player" title="Tela Cheia">
                        Tela Cheia
                    </button>
                    <button type="button" class="btn-player-action" id="btn-external-player" title="Abrir em Nova Aba com segurança">
                        Nova Aba
                    </button>
                </div>
            </div>

            <div class="servers-selector-container">
                ${hasSources ? `
                    <div class="server-group">
