                            ${directServersHtml}
                        </div>
                    </div>
                ` : ''}
                ${hasContingency ? `
                    <div class="server-group">
                        <span class="server-group-label">Servidores de Contingência (Embeds Alternativos):</span>
                        <div class="servers-pills-row" id="contingency-servers-grid">
                            ${contingencyServersHtml}
                        </div>
                    </div>
                ` : ''}
            </div>
        </div>
    `;

    setupTvPlayerControls(activeChannel);

    // Initial mount based on serverType
    if (activeChannel.serverType === 'direct') {
        mountTvDirectStream(activeChannel.data, activeChannel.sourceIndex, () => {
            handleAllDirectSourcesFailed(() => selectChannel(activeChannel.category, activeChannel.name, activeChannel.data));
        });
    } else {
        mountTvContingencyIframe(activeChannel.contingencyUrl);
    }
}

function setupTvPlayerControls(activeChannel) {
    const btnReload = document.getElementById("btn-reload-player");
    const btnFullscreen = document.getElementById("btn-fullscreen-player");
    const btnExternal = document.getElementById("btn-external-player");
    const btnFavCurrent = document.getElementById("btn-fav-current");

    if (btnReload) {
        btnReload.onclick = () => {
            if (activeChannel.serverType === 'direct') {
                mountTvDirectStream(activeChannel.data, activeChannel.sourceIndex);
            } else {
                mountTvContingencyIframe(activeChannel.contingencyUrl);
            }
            showToast("Recarregando player...");
        };
    }

    if (btnFullscreen) {
        btnFullscreen.onclick = () => {
            const art = window.tvArtInstance;
            if (art && art.fullscreen) {
                art.fullscreen.toggle();
            } else {
                const vidContainer = document.getElementById("video-container");
                if (vidContainer) {
                    if (!document.fullscreenElement) vidContainer.requestFullscreen().catch(() => {});
                    else document.exitFullscreen().catch(() => {});
                }
            }
        };
    }

    if (btnExternal) {
        btnExternal.onclick = () => {
            let urlToOpen = "";
            if (activeChannel.serverType === 'direct') {
                const src = activeChannel.data.sources[activeChannel.sourceIndex];
                urlToOpen = src ? src.url : "";
            } else {
                urlToOpen = activeChannel.contingencyUrl || "";
            }
            if (urlToOpen) {
                if (window.tvzinhaSafeOpen) {
                    window.tvzinhaSafeOpen(urlToOpen, "_blank", "noopener,noreferrer");
                } else {
                    window.open(urlToOpen, "_blank", "noopener,noreferrer");
                }
            }
        };
    }

    if (btnFavCurrent) {
        btnFavCurrent.onclick = () => {
            const isFav = store.toggleFavorite(activeChannel.name);
            btnFavCurrent.classList.toggle("active", isFav);
            btnFavCurrent.innerHTML = isFav ? getUiSvg('starFilled', 16) : getUiSvg('star', 16);
            showToast(isFav ? `${activeChannel.name} adicionado aos favoritos` : `${activeChannel.name} removido dos favoritos`);
        };
    }

    // Server Pills event delegation
    const directGrid = document.getElementById("direct-servers-grid");
    if (directGrid) {
        directGrid.addEventListener("click", (e) => {
            const btn = e.target.closest(".btn-server-option");
            if (!btn) return;
            const idx = parseInt(btn.dataset.sourceIndex, 10);
            activeChannel.serverType = 'direct';
            activeChannel.sourceIndex = idx;
            updateServerPillsActive(btn);
            mountTvDirectStream(activeChannel.data, idx);
        });
    }

    const contingencyGrid = document.getElementById("contingency-servers-grid");
    if (contingencyGrid) {
        contingencyGrid.addEventListener("click", (e) => {
            const btn = e.target.closest(".btn-server-option");
            if (!btn) return;
            const url = btn.dataset.contingencyUrl;
            activeChannel.serverType = 'contingency';
            activeChannel.contingencyUrl = url;
            updateServerPillsActive(btn);
            mountTvContingencyIframe(url);
        });
    }
}

function updateServerPillsActive(clickedBtn) {
    document.querySelectorAll(".btn-server-option").forEach(b => b.classList.remove("active"));
    if (clickedBtn) clickedBtn.classList.add("active");
}

function setupSidebarResizer() {
    const sidebar = document.getElementById("sidebar");
    const sidebarResizer = document.getElementById("sidebar-resizer");
    if (!sidebar || !sidebarResizer) return;

    let isResizing = false;
    sidebarResizer.addEventListener("mousedown", (e) => {
        if (window.innerWidth <= 768) return;
        e.preventDefault();
        isResizing = true;
        document.body.classList.add("is-resizing");

        function onMouseMove(moveEvent) {
            if (!isResizing) return;
            const newWidth = Math.max(240, Math.min(600, moveEvent.clientX));
            sidebar.style.width = newWidth + "px";
        }

        function onMouseUp() {
            if (isResizing) {
                isResizing = false;
                document.body.classList.remove("is-resizing");
                window.removeEventListener("mousemove", onMouseMove);
                window.removeEventListener("mouseup", onMouseUp);
            }
        }

        window.addEventListener("mousemove", onMouseMove);
        window.addEventListener("mouseup", onMouseUp);
    });
}

