/**
 * TVZINHA ONLINE - Movies Catalog & Cinema Module (TMDB Engine)
 * Handles movies discovery, TMDB pagination, search filters, masters/studios sections, and modal playback
 */

import { store } from '../core/state.js';
import {
    TMDB_API_KEY,
    TMDB_BASE_URL,
    TMDB_IMG_W500,
    TMDB_IMG_ORIGINAL,
    TMDB_CACHE_KEY,
    TMDB_CACHE_TTL_MS,
    FAMOUS_DIRECTORS,
    FAMOUS_STUDIOS,
    MOVIE_SERVERS
} from '../core/constants.js';
import { showToast } from '../core/toast.js';
import { setPlaybackActiveState } from '../core/wakeLock.js';
import { getUiSvg } from '../core/icons.js';
import { mountNativePlayer, resolveDirectStream, atomicPlayerReset } from '../player/engine.js';

let isMoviesInitialized = false;
let moviesCacheData = null;
let currentSelectedMovie = null;
let activeMovieServer = null;
let movieSearchDebounceTimer = null;

let activeFilterGenre = '';
let activeFilterYearRange = '';
let activeFilterSort = 'popularity.desc';

export async function fetchTmdbEndpoint(path) {
    const separator = path.includes('?') ? '&' : '?';
    const url = `${TMDB_BASE_URL}/${path}${separator}api_key=${TMDB_API_KEY}&language=pt-BR`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`TMDB HTTP error ${res.status}`);
    return await res.json();
}

export async function initMoviesView() {
    if (isMoviesInitialized) return;
    isMoviesInitialized = true;

    setupMoviesSearchAndFilters();
    setupMovieModal();
    setupMoviesCarouselNavigation();

    // Check localStorage cache
    try {
        const rawCache = localStorage.getItem(TMDB_CACHE_KEY);
        if (rawCache) {
            const parsed = JSON.parse(rawCache);
            if (parsed && parsed.timestamp && (Date.now() - parsed.timestamp < TMDB_CACHE_TTL_MS)) {
                moviesCacheData = parsed.data;
                renderMoviesDiscoveryFeed(moviesCacheData);
                return;
            }
        }
    } catch (e) {
        console.warn("[Movies] Falha ao ler cache:", e);
    }

    await loadMoviesFromTmdb();
}

function deduplicateFeedRows(sections) {
    const seenIds = new Set();
    const result = {};
    for (const [key, list] of Object.entries(sections)) {
        result[key] = [];
        for (const item of (list || [])) {
            if (item && item.id && !seenIds.has(item.id)) {
                seenIds.add(item.id);
                result[key].push(item);
            }
        }
    }
    return result;
}

export async function loadMoviesFromTmdb() {
    const loader = document.getElementById("movies-feed-loader");
    if (loader) loader.classList.remove("hidden");

    try {
        const [trending, action, scifi, animation, horror, drama, comedy, classic] = await Promise.all([
            fetchTmdbEndpoint('trending/movie/week').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=28&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=878&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=16&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=27&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=18&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?with_genres=35&sort_by=popularity.desc').then(d => d.results || []),
            fetchTmdbEndpoint('discover/movie?vote_count.gte=1000&sort_by=vote_average.desc').then(d => d.results || [])
        ]);

        const rawFeed = {
            hero: trending.slice(0, 5),
            trending: trending.slice(5),
            action,
            scifi,
            animation,
            horror,
            drama,
            comedy,
            classic
        };

        moviesCacheData = deduplicateFeedRows(rawFeed);

        try {
            localStorage.setItem(TMDB_CACHE_KEY, JSON.stringify({
                timestamp: Date.now(),
                data: moviesCacheData
            }));
        } catch (e) {}

        renderMoviesDiscoveryFeed(moviesCacheData);
    } catch (err) {
        console.error("[Movies] Erro ao carregar catálogo TMDB:", err);
        showToast("Erro ao carregar catálogo de filmes.");
    } finally {
        if (loader) loader.classList.add("hidden");
    }
}

export function renderMoviesDiscoveryFeed(feed) {
    if (!feed) return;
    renderHeroCarousel(feed.hero || []);
    renderMovieCarouselRow("row-trending", feed.trending || []);
    renderMovieCarouselRow("row-action", feed.action || []);
    renderMovieCarouselRow("row-scifi", feed.scifi || []);
    renderMovieCarouselRow("row-animation", feed.animation || []);
    renderMovieCarouselRow("row-horror", feed.horror || []);
    renderMovieCarouselRow("row-drama", feed.drama || []);
    renderMovieCarouselRow("row-comedy", feed.comedy || []);
    renderMovieCarouselRow("row-classic", feed.classic || []);
    renderCuratedSections();
}

function renderHeroCarousel(heroItems) {
    const heroContainer = document.getElementById("movies-hero-carousel");
    if (!heroContainer || !heroItems || heroItems.length === 0) return;

    const item = heroItems[0];
    const backdropUrl = item.backdrop_path ? `${TMDB_IMG_ORIGINAL}${item.backdrop_path}` : '';
    const year = (item.release_date || '').slice(0, 4);
    const rating = item.vote_average ? item.vote_average.toFixed(1) : '7.5';

    heroContainer.innerHTML = `
        <div class="movies-hero-backdrop" style="background-image: url('${backdropUrl}');"></div>
        <div class="movies-hero-overlay"></div>
        <div class="movies-hero-content">
            <span class="movies-hero-badge">Destaque da Semana</span>
            <h1 class="movies-hero-title">${item.title || item.name}</h1>
            <div class="movies-hero-meta">
                <span class="meta-rating">★ ${rating}</span>
                <span class="meta-year">${year}</span>
            </div>
            <p class="movies-hero-overview">${(item.overview || 'Sem sinopse disponível.').slice(0, 220)}...</p>
            <div class="movies-hero-actions">
                <button type="button" class="btn-hero-watch" id="btn-hero-watch-movie">
                    ▶ Assistir Agora
                </button>
            </div>
        </div>
    `;

    const btnWatch = document.getElementById("btn-hero-watch-movie");
    if (btnWatch) {
        btnWatch.onclick = () => openMovieDetailsModal(item);
    }
}

function renderMovieCarouselRow(rowId, movies) {
    const rowEl = document.getElementById(rowId);
    if (!rowEl || !movies || movies.length === 0) return;

    rowEl.innerHTML = "";
    movies.forEach(movie => {
        if (!movie.poster_path) return;
        const card = document.createElement("div");
        card.className = "movie-poster-card";
        card.tabIndex = 0;

        const posterUrl = `${TMDB_IMG_W500}${movie.poster_path}`;
        const year = (movie.release_date || '').slice(0, 4);
        const rating = movie.vote_average ? movie.vote_average.toFixed(1) : '';

        card.innerHTML = `
            <img src="${posterUrl}" alt="${movie.title}" class="movie-poster-img" loading="lazy">
            <div class="movie-poster-info">
                <span class="movie-poster-title">${movie.title}</span>
                <div class="movie-poster-meta">
                    <span>${year}</span>
                    ${rating ? `<span>★ ${rating}</span>` : ''}
                </div>
            </div>
        `;

        card.onclick = () => openMovieDetailsModal(movie);
        rowEl.appendChild(card);
    });
}

function renderCuratedSections() {
    const directorsRow = document.getElementById("row-masters-cinema");
    if (directorsRow) {
        directorsRow.innerHTML = "";
        FAMOUS_DIRECTORS.forEach(dir => {
            const card = document.createElement("div");
            card.className = "director-card";
            card.tabIndex = 0;
            card.innerHTML = `
                <img src="${dir.photo}" alt="${dir.name}" class="director-photo" loading="lazy">
                <span class="director-name">${dir.name}</span>
                <span class="director-known">${dir.knownFor}</span>
            `;
            card.onclick = async () => {
                showToast(`Buscando obras de ${dir.name}...`);
                const res = await fetchTmdbEndpoint(`discover/movie?with_people=${dir.id}&sort_by=popularity.desc`);
                if (res && res.results) {
                    renderMovieCarouselRow("row-trending", res.results);
                    document.getElementById("row-trending")?.scrollIntoView({ behavior: 'smooth' });
                }
            };
            directorsRow.appendChild(card);
        });
    }

    const studiosRow = document.getElementById("row-famous-studios");
    if (studiosRow) {
        studiosRow.innerHTML = "";
        FAMOUS_STUDIOS.forEach(std => {
            const card = document.createElement("div");
            card.className = "studio-card";
            card.tabIndex = 0;
            card.innerHTML = `
                <img src="${std.logo}" alt="${std.name}" class="studio-logo" loading="lazy">
                <span class="studio-name">${std.name}</span>
            `;
            card.onclick = async () => {
                showToast(`Buscando catálogo de ${std.name}...`);
                const res = await fetchTmdbEndpoint(`discover/movie?with_companies=${std.id}&sort_by=popularity.desc`);
                if (res && res.results) {
                    renderMovieCarouselRow("row-trending", res.results);
                    document.getElementById("row-trending")?.scrollIntoView({ behavior: 'smooth' });
                }
            };
            studiosRow.appendChild(card);
        });
    }
}

export function openMovieDetailsModal(movie) {
    currentSelectedMovie = movie;
    const modal = document.getElementById("movie-modal");
    if (!modal) return;

    const titleEl = document.getElementById("movie-modal-title");
    const overviewEl = document.getElementById("movie-modal-overview");
    const yearEl = document.getElementById("movie-modal-year");
    const ratingEl = document.getElementById("movie-modal-rating");
    const posterEl = document.getElementById("movie-modal-poster");

    if (titleEl) titleEl.textContent = movie.title || movie.name;
    if (overviewEl) overviewEl.textContent = movie.overview || "Sem sinopse disponível.";
    if (yearEl) yearEl.textContent = (movie.release_date || '').slice(0, 4);
    if (ratingEl) ratingEl.textContent = movie.vote_average ? `★ ${movie.vote_average.toFixed(1)}` : '';
    if (posterEl && movie.poster_path) posterEl.src = `${TMDB_IMG_W500}${movie.poster_path}`;

    buildMovieServerButtons();
    modal.classList.remove("hidden");
    document.body.style.overflow = "hidden";

    // Play default native direct server
    playMovieServer('native_direct');
}

export function closeMovieDetailsModal() {
    setPlaybackActiveState(false);
    atomicPlayerReset();
    if (typeof window !== 'undefined' && window.tvzinhaSetContingencyState) {
        window.tvzinhaSetContingencyState(false);
    }

    const modal = document.getElementById("movie-modal");
    const iframe = document.getElementById("movie-modal-iframe");
    const movieLoader = document.getElementById("movie-player-loader");
    const modalCard = document.querySelector(".movie-modal-card");

    if (iframe) iframe.src = "";
    if (movieLoader) movieLoader.classList.add("hidden");
    if (modal) modal.classList.add("hidden");
    if (modalCard) modalCard.classList.remove("is-playing");
    document.body.style.overflow = "";
    currentSelectedMovie = null;
    activeMovieServer = null;
}

function buildMovieServerButtons() {
    const pillsRow = document.getElementById("movie-servers-pills");
    if (!pillsRow) return;

    pillsRow.innerHTML = `
        <button type="button" class="btn-movie-server-pill active" data-server="native_direct">Player Nativo - Sem Anúncios (BETA)</button>
    `;

    MOVIE_SERVERS.forEach(srv => {
        pillsRow.innerHTML += `
            <button type="button" class="btn-movie-server-pill" data-server="${srv.id}">${srv.name}</button>
        `;
    });

    pillsRow.onclick = (e) => {
        const btn = e.target.closest(".btn-movie-server-pill");
        if (!btn) return;
        pillsRow.querySelectorAll(".btn-movie-server-pill").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        playMovieServer(btn.dataset.server);
    };
}

export async function playMovieServer(serverKey) {
    if (!currentSelectedMovie) return;
    activeMovieServer = serverKey;

    const playerContainer = document.getElementById("movie-player-container");
    const movieArt = document.getElementById("movie-artplayer-container");
    const iframe = document.getElementById("movie-modal-iframe");
    const movieLoader = document.getElementById("movie-player-loader");
    const modalCard = document.querySelector(".movie-modal-card");

    if (modalCard) modalCard.classList.add("is-playing");
    if (movieLoader) movieLoader.classList.remove("hidden");

    if (serverKey === 'native_direct') {
        if (typeof window !== 'undefined' && window.tvzinhaSetContingencyState) {
            window.tvzinhaSetContingencyState(false);
        }
        if (iframe) {
            iframe.src = "";
            iframe.classList.add("hidden");
        }

        try {
            const resolved = await resolveDirectStream({
                id: currentSelectedMovie.id,
                type: 'movie',
                title: currentSelectedMovie.title
            });

            if (movieLoader) movieLoader.classList.add("hidden");

            if (resolved && resolved.stream_url) {
                mountNativePlayer({
                    containerId: 'movie-artplayer-container',
                    streamUrl: resolved.stream_url,
                    title: currentSelectedMovie.title,
                    poster: currentSelectedMovie.backdrop_path ? `${TMDB_IMG_ORIGINAL}${currentSelectedMovie.backdrop_path}` : '',
                    fallbackSources: resolved.sources || [],
                    onAllFailed: () => {
                        showToast("Fonte direta indisponível. Alterne para um servidor alternativo.");
                    }
                });
            } else {
                showToast("Transmissão nativa não localizada. Alterne para os servidores abaixo.");
            }
        } catch (err) {
            if (movieLoader) movieLoader.classList.add("hidden");
            showToast("Erro ao conectar ao motor nativo.");
        }
        return;
    }

    // Legacy Iframe Servers
    atomicPlayerReset();
    if (movieArt) movieArt.classList.add("hidden");
    if (iframe) {
        if (typeof window !== 'undefined') {
            if (window.tvzinhaArmIframeGuard) window.tvzinhaArmIframeGuard(iframe);
            if (window.tvzinhaSetContingencyState) window.tvzinhaSetContingencyState(true);
        }
        iframe.classList.remove("hidden");
        const serverDef = MOVIE_SERVERS.find(s => s.id === serverKey) || MOVIE_SERVERS[0];
        iframe.src = serverDef.buildUrl(currentSelectedMovie.id);
        iframe.onload = () => {
            if (movieLoader) movieLoader.classList.add("hidden");
            setPlaybackActiveState(true);
        };
        setTimeout(() => {
            if (movieLoader) movieLoader.classList.add("hidden");
        }, 3000);
    }
}

function setupMovieModal() {
    const modal = document.getElementById("movie-modal");
    const btnClose = document.getElementById("btn-close-movie-modal");
    if (btnClose) btnClose.onclick = closeMovieDetailsModal;
    if (modal) {
        modal.onclick = (e) => {
            if (e.target === modal) closeMovieDetailsModal();
        };
    }
}

function setupMoviesSearchAndFilters() {
    const searchInput = document.getElementById("movies-search-input");
    if (searchInput) {
        searchInput.addEventListener("input", (e) => {
            clearTimeout(movieSearchDebounceTimer);
            const query = e.target.value.trim();
            movieSearchDebounceTimer = setTimeout(async () => {
                if (query.length > 2) {
                    showToast(`Buscando "${query}"...`);
                    const res = await fetchTmdbEndpoint(`search/movie?query=${encodeURIComponent(query)}`);
                    if (res && res.results) {
                        renderMovieCarouselRow("row-trending", res.results);
                        document.getElementById("row-trending")?.scrollIntoView({ behavior: 'smooth' });
                    }
                } else if (query.length === 0 && moviesCacheData) {
                    renderMoviesDiscoveryFeed(moviesCacheData);
                }
            }, 500);
        });
    }
}

function setupMoviesCarouselNavigation() {
    document.querySelectorAll(".carousel-nav-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            const targetId = btn.dataset.target;
            const targetRow = document.getElementById(targetId);
            if (targetRow) {
                const dir = btn.dataset.direction === 'prev' ? -400 : 400;
                targetRow.scrollBy({ left: dir, behavior: 'smooth' });
            }
        });
    });
}

