/**
 * TVZINHA ONLINE - Series & Animes Catalog Module
 * Handles TMDB series/animes feeds, seasons & episodes drawer, watch progress and theater player
 */

import { store } from '../core/state.js';
import {
    TMDB_API_KEY,
    TMDB_BASE_URL,
    TMDB_IMG_W500,
    TMDB_IMG_ORIGINAL,
    TMDB_SERIES_CACHE_KEY,
    TMDB_ANIMES_CACHE_KEY,
    WATCH_PROGRESS_KEY,
    SERIES_SERVERS
} from '../core/constants.js';
import { showToast } from '../core/toast.js';
import { setPlaybackActiveState } from '../core/wakeLock.js';
import { getUiSvg } from '../core/icons.js';
import { mountNativePlayer, resolveDirectStream, atomicPlayerReset } from '../player/engine.js';

let isSeriesInitialized = false;
let isAnimesInitialized = false;
let activeAnimeFilter = false;

let currentSelectedSeries = null;
let currentSeriesDetails = null;
const cachedSeasonsMap = {};

let activeSeriesPlaying = {
    show: null,
    seasonNumber: 1,
    episodeNumber: 1,
    episodeData: null,
    server: 'native_direct'
};

export function getStoredWatchProgress() {
    try {
        const raw = localStorage.getItem(WATCH_PROGRESS_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch (e) {
        return {};
    }
}

export function saveStoredWatchProgress(show, season, episode, epTitle, mediaType = 'tv') {
    try {
        const progress = getStoredWatchProgress();
        progress[show.id] = {
            id: show.id,
            title: show.name || show.title,
            poster_path: show.poster_path,
            backdrop_path: show.backdrop_path,
            season: Number(season),
            episode: Number(episode),
            episodeTitle: epTitle || `Episódio ${episode}`,
            mediaType: mediaType,
            timestamp: Date.now()
        };
        localStorage.setItem(WATCH_PROGRESS_KEY, JSON.stringify(progress));
        renderHomeContinueWatching();
    } catch (e) {
        console.warn("[Series] Falha ao salvar histórico de episódios:", e);
    }
}

export function renderHomeContinueWatching() {
    const section = document.getElementById("home-continue-watching-section");
    const track = document.getElementById("home-continue-watching-track");
    if (!section || !track) return;

    const progress = getStoredWatchProgress();
    const items = Object.values(progress).sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

    if (items.length === 0) {
        section.classList.add("hidden");
        track.innerHTML = "";
        return;
    }

    section.classList.remove("hidden");
    track.innerHTML = "";

    items.forEach(item => {
        const card = document.createElement("div");
        card.className = "continue-watching-card";
        card.tabIndex = 0;

        const imgUrl = item.backdrop_path
            ? `${TMDB_IMG_W500}${item.backdrop_path}`
            : (item.poster_path ? `${TMDB_IMG_W500}${item.poster_path}` : '');

        card.innerHTML = `
            <div class="continue-card-thumb" style="background-image: url('${imgUrl}');">
                <span class="continue-play-badge">▶</span>
            </div>
            <div class="continue-card-meta">
                <span class="continue-card-title">${item.title}</span>
                <span class="continue-card-ep">T${item.season} E${item.episode} • ${item.episodeTitle}</span>
            </div>
        `;

        card.onclick = () => {
            playSeriesEpisode(item, item.season, item.episode, { name: item.episodeTitle });
        };

        track.appendChild(card);
    });
}

export async function fetchSeriesEndpoint(path) {
    const separator = path.includes('?') ? '&' : '?';
    const url = `${TMDB_BASE_URL}/${path}${separator}api_key=${TMDB_API_KEY}&language=pt-BR`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`TMDB Series error ${res.status}`);
    return await res.json();
}

export async function initSeriesView() {
    if (isSeriesInitialized) return;
    isSeriesInitialized = true;
    setupSeriesModalHandlers();
    renderHomeContinueWatching();
    await loadSeriesCatalog();
}

export async function initAnimesView() {
    if (isAnimesInitialized) return;
    isAnimesInitialized = true;
    setupSeriesModalHandlers();
    await loadAnimesCatalog();
}

export async function loadSeriesCatalog() {
    const loader = document.getElementById("series-feed-loader");
    if (loader) loader.classList.remove("hidden");

    try {
        const [trending, drama, scifi, action, comedy] = await Promise.all([
            fetchSeriesEndpoint('trending/tv/week').then(d => d.results || []),
            fetchSeriesEndpoint('discover/tv?with_genres=18&sort_by=popularity.desc').then(d => d.results || []),
            fetchSeriesEndpoint('discover/tv?with_genres=10765&sort_by=popularity.desc').then(d => d.results || []),
            fetchSeriesEndpoint('discover/tv?with_genres=10759&sort_by=popularity.desc').then(d => d.results || []),
            fetchSeriesEndpoint('discover/tv?with_genres=35&sort_by=popularity.desc').then(d => d.results || [])
        ]);

        renderSeriesDiscoveryFeed({
            trending,
            drama,
            scifi,
            action,
            comedy
        });
    } catch (err) {
        console.error("[Series] Erro ao carregar catálogo:", err);
    } finally {
        if (loader) loader.classList.add("hidden");
    }
}

export async function loadAnimesCatalog() {
    const loader = document.getElementById("animes-feed-loader");
    if (loader) loader.classList.remove("hidden");

    try {
        const [shonen, trendingAnimes, moviesAnime] = await Promise.all([
            fetchSeriesEndpoint('discover/tv?with_genres=16&with_keywords=210024|287501&sort_by=popularity.desc').then(d => d.results || []),
            fetchSeriesEndpoint('discover/tv?with_genres=16&with_original_language=ja&sort_by=popularity.desc').then(d => d.results || []),
            fetchSeriesEndpoint('discover/movie?with_genres=16&with_original_language=ja&sort_by=popularity.desc').then(d => d.results || [])
        ]);

        renderAnimesDiscoveryFeed({
            shonen,
            trendingAnimes,
            moviesAnime
        });
    } catch (err) {
        console.error("[Animes] Erro ao carregar animes:", err);
    } finally {
        if (loader) loader.classList.add("hidden");
    }
}

function renderSeriesDiscoveryFeed(feed) {
    renderSeriesRow("row-series-trending", feed.trending || []);
    renderSeriesRow("row-series-drama", feed.drama || []);
    renderSeriesRow("row-series-scifi", feed.scifi || []);
    renderSeriesRow("row-series-action", feed.action || []);
    renderSeriesRow("row-series-comedy", feed.comedy || []);
}

function renderAnimesDiscoveryFeed(feed) {
    renderSeriesRow("row-animes-trending", feed.trendingAnimes || []);
    renderSeriesRow("row-animes-shonen", feed.shonen || []);
    renderSeriesRow("row-animes-movies", feed.moviesAnime || []);
}

function renderSeriesRow(rowId, list) {
    const rowEl = document.getElementById(rowId);
    if (!rowEl || !list || list.length === 0) return;

    rowEl.innerHTML = "";
    list.forEach(show => {
        if (!show.poster_path) return;
        const card = document.createElement("div");
        card.className = "movie-poster-card";
        card.tabIndex = 0;

        const posterUrl = `${TMDB_IMG_W500}${show.poster_path}`;
        const year = (show.first_air_date || show.release_date || '').slice(0, 4);
        const rating = show.vote_average ? show.vote_average.toFixed(1) : '';

        card.innerHTML = `
            <img src="${posterUrl}" alt="${show.name || show.title}" class="movie-poster-img" loading="lazy">
            <div class="movie-poster-info">
                <span class="movie-poster-title">${show.name || show.title}</span>
                <div class="movie-poster-meta">
                    <span>${year}</span>
                    ${rating ? `<span>★ ${rating}</span>` : ''}
                </div>
            </div>
        `;

        card.onclick = () => openSeriesDetailsModal(show);
        rowEl.appendChild(card);
    });
}

export async function openSeriesDetailsModal(show) {
    currentSelectedSeries = show;
    const modal = document.getElementById("series-modal");
    if (!modal) return;

    const titleEl = document.getElementById("series-modal-title");
    const overviewEl = document.getElementById("series-modal-overview");
    const yearEl = document.getElementById("series-modal-year");
    const ratingEl = document.getElementById("series-modal-rating");
    const posterEl = document.getElementById("series-modal-poster");

    if (titleEl) titleEl.textContent = show.name || show.title;
    if (overviewEl) overviewEl.textContent = show.overview || "Sem sinopse disponível.";
    if (yearEl) yearEl.textContent = (show.first_air_date || show.release_date || '').slice(0, 4);
    if (ratingEl) ratingEl.textContent = show.vote_average ? `★ ${show.vote_average.toFixed(1)}` : '';
    if (posterEl && show.poster_path) posterEl.src = `${TMDB_IMG_W500}${show.poster_path}`;

    modal.classList.remove("hidden");
    document.body.style.overflow = "hidden";

    await loadSeriesSeasons(show.id);
}

async function loadSeriesSeasons(seriesId) {
    const seasonsSelector = document.getElementById("series-season-select");
    if (!seasonsSelector) return;

    try {
        const details = await fetchSeriesEndpoint(`tv/${seriesId}`);
        currentSeriesDetails = details;
        const seasons = (details.seasons || []).filter(s => s.season_number > 0);

        seasonsSelector.innerHTML = "";
        seasons.forEach((s, idx) => {
            const opt = document.createElement("option");
            opt.value = s.season_number;
            opt.textContent = s.name || `Temporada ${s.season_number}`;
            if (idx === 0) opt.selected = true;
            seasonsSelector.appendChild(opt);
        });

        seasonsSelector.onchange = () => {
            loadEpisodesForSeason(seriesId, seasonsSelector.value);
        };

        if (seasons.length > 0) {
            loadEpisodesForSeason(seriesId, seasons[0].season_number);
        }
    } catch (e) {
        console.warn("[Series] Erro ao carregar temporadas:", e);
    }
}

async function loadEpisodesForSeason(seriesId, seasonNum) {
    const grid = document.getElementById("series-episodes-grid");
    if (!grid) return;
    grid.innerHTML = `<div class="episodes-loading-spinner"><div class="spinner"></div><span>Carregando episódios...</span></div>`;

    const cacheKey = `${seriesId}_${seasonNum}`;
    let episodes = cachedSeasonsMap[cacheKey];

    if (!episodes) {
        try {
            const res = await fetchSeriesEndpoint(`tv/${seriesId}/season/${seasonNum}`);
            episodes = res.episodes || [];
            cachedSeasonsMap[cacheKey] = episodes;
        } catch (e) {
            grid.innerHTML = `<p class="episodes-error">Erro ao carregar episódios da temporada.</p>`;
            return;
        }
    }

    grid.innerHTML = "";
    episodes.forEach(ep => {
        const card = document.createElement("div");
        card.className = "series-ep-card";
        card.tabIndex = 0;

        const thumb = ep.still_path ? `${TMDB_IMG_W500}${ep.still_path}` : '';

        card.innerHTML = `
            <div class="ep-card-thumb" style="background-image: url('${thumb}');">
                <span class="ep-num">Ep. ${ep.episode_number}</span>
            </div>
            <div class="ep-card-info">
                <span class="ep-title">${ep.name || `Episódio ${ep.episode_number}`}</span>
                <span class="ep-air">${ep.air_date || ''}</span>
            </div>
        `;

        card.onclick = () => {
            playSeriesEpisode(currentSelectedSeries, seasonNum, ep.episode_number, ep);
        };

        grid.appendChild(card);
    });
}

export async function playSeriesEpisode(showItem, seasonNumber, episodeNumber, epData = null, serverKey = 'native_direct') {
    activeSeriesPlaying = {
        show: showItem,
        seasonNumber: Number(seasonNumber),
        episodeNumber: Number(episodeNumber),
        episodeData: epData,
        server: serverKey
    };

    const detailsModal = document.getElementById("series-modal");
    if (detailsModal) detailsModal.classList.add("hidden");

    const theaterView = document.getElementById("series-player-view");
    if (theaterView) theaterView.classList.remove("hidden");

    const titleEl = document.getElementById("series-theater-title");
    const epTitleEl = document.getElementById("series-theater-ep-title");
    if (titleEl) titleEl.textContent = showItem.name || showItem.title;
    if (epTitleEl) epTitleEl.textContent = `T${seasonNumber} E${episodeNumber} • ${epData ? epData.name : ''}`;

    setupSeriesServerPills();

    const seriesArt = document.getElementById("series-artplayer-container");
    const iframe = document.getElementById("series-modal-iframe");
    const seriesLoader = document.getElementById("series-theater-loader");

    if (seriesLoader) seriesLoader.classList.remove("hidden");

    if (serverKey === 'native_direct' || serverKey === 'native_anime') {
        if (typeof window !== 'undefined' && window.tvzinhaSetContingencyState) {
            window.tvzinhaSetContingencyState(false);
        }
        if (iframe) {
            iframe.src = "";
            iframe.classList.add("hidden");
        }

        try {
            const resolved = await resolveDirectStream({
                id: showItem.id,
                type: 'tv',
                season: seasonNumber,
                episode: episodeNumber,
                title: showItem.name || showItem.title
            });

            if (seriesLoader) seriesLoader.classList.add("hidden");

            if (resolved && resolved.stream_url) {
                mountNativePlayer({
                    containerId: 'series-artplayer-container',
                    streamUrl: resolved.stream_url,
                    title: `${showItem.name || showItem.title} - T${seasonNumber}E${episodeNumber}`,
                    fallbackSources: resolved.sources || [],
                    onAllFailed: () => {
                        showToast("Fonte nativa indisponível. Alterne para Superflix ou MGEB.");
                    }
                });
            } else {
                showToast("Stream nativo indisponível. Alterne para servidores alternativos.");
            }
        } catch (e) {
            if (seriesLoader) seriesLoader.classList.add("hidden");
            showToast("Erro ao conectar ao motor nativo.");
        }
        saveStoredWatchProgress(showItem, seasonNumber, episodeNumber, epData ? epData.name : `Episódio ${episodeNumber}`);
        return;
    }

    // Legacy Iframe Servers
    atomicPlayerReset();
    if (seriesArt) seriesArt.classList.add("hidden");
    if (iframe) {
        if (typeof window !== 'undefined') {
            if (window.tvzinhaArmIframeGuard) window.tvzinhaArmIframeGuard(iframe);
            if (window.tvzinhaSetContingencyState) window.tvzinhaSetContingencyState(true);
        }
        iframe.classList.remove("hidden");
        const serverDef = SERIES_SERVERS[serverKey] || SERIES_SERVERS.mgeb;
        iframe.src = serverDef.buildUrl(showItem.id, seasonNumber, episodeNumber);
        iframe.onload = () => {
            if (seriesLoader) seriesLoader.classList.add("hidden");
            setPlaybackActiveState(true);
        };
        setTimeout(() => {
            if (seriesLoader) seriesLoader.classList.add("hidden");
        }, 3000);
    }

    saveStoredWatchProgress(showItem, seasonNumber, episodeNumber, epData ? epData.name : `Episódio ${episodeNumber}`);
}

function setupSeriesServerPills() {
    const pillsContainer = document.getElementById("series-server-pills");
    if (!pillsContainer) return;

    pillsContainer.onclick = (e) => {
        const btn = e.target.closest(".btn-series-server-pill");
        if (!btn) return;
        pillsContainer.querySelectorAll(".btn-series-server-pill").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        playSeriesEpisode(
            activeSeriesPlaying.show,
            activeSeriesPlaying.seasonNumber,
            activeSeriesPlaying.episodeNumber,
            activeSeriesPlaying.episodeData,
            btn.dataset.server
        );
    };
}

export function stopSeriesPlayer() {
    setPlaybackActiveState(false);
    atomicPlayerReset();
    if (typeof window !== 'undefined' && window.tvzinhaSetContingencyState) {
        window.tvzinhaSetContingencyState(false);
    }

    const theaterView = document.getElementById("series-player-view");
    const iframe = document.getElementById("series-modal-iframe");
    const seriesLoader = document.getElementById("series-theater-loader");

    if (iframe) iframe.src = "";
    if (seriesLoader) seriesLoader.classList.add("hidden");
    if (theaterView) theaterView.classList.add("hidden");

    const detailsModal = document.getElementById("series-modal");
    if (detailsModal && currentSelectedSeries) {
        detailsModal.classList.remove("hidden");
    }
}

export function setupSeriesModalHandlers() {
    const btnCloseDetails = document.getElementById("btn-close-series-modal");
    if (btnCloseDetails) {
        btnCloseDetails.onclick = () => {
            const modal = document.getElementById("series-modal");
            if (modal) modal.classList.add("hidden");
            document.body.style.overflow = "";
        };
    }

    const btnBackTheater = document.getElementById("btn-series-back");
    if (btnBackTheater) {
        btnBackTheater.onclick = stopSeriesPlayer;
    }
}

