/**
 * TVZINHA ONLINE - SPA Router & Layout Navigation Capsule
 * Handles view switching, active navigation state, mobile drawer, and player lifecycle/audio teardown
 */

import { store } from '../core/state.js';
import { atomicTvPlayerReset } from '../player/engine.js';
import { setPlaybackActiveState } from '../core/wakeLock.js';

let viewHooks = {
    onHome: null,
    onMovies: null,
    onSeries: null,
    onAnimes: null,
    onTv: null
};

export function registerViewHook(viewName, callback) {
    if (viewHooks[viewName] !== undefined) {
        viewHooks[viewName] = callback;
    }
}

export function openMobileMenu() {
    const sidebar = document.getElementById("sidebar");
    const backdrop = document.getElementById("sidebar-backdrop");
    if (sidebar) sidebar.classList.add("open");
    if (backdrop) backdrop.classList.add("active");
    document.body.classList.add("sidebar-open");
    document.body.style.overflow = "hidden";
}

export function closeMobileMenu() {
    const sidebar = document.getElementById("sidebar");
    const backdrop = document.getElementById("sidebar-backdrop");
    if (sidebar) sidebar.classList.remove("open");
    if (backdrop) backdrop.classList.remove("active");
    document.body.classList.remove("sidebar-open");
    document.body.style.overflow = "";
}

export function switchAppView(viewName) {
    if (!viewName) return;

    // Teardown TV playback and audio when switching away from TV view
    if (viewName !== 'tv') {
        closeMobileMenu();
        atomicTvPlayerReset();

        const isMovieModalActive = !document.getElementById("movie-modal")?.classList.contains("hidden");
        const isSeriesPlayerActive = !document.getElementById("series-player-view")?.classList.contains("hidden");
        if (!isMovieModalActive && !isSeriesPlayerActive) {
            setPlaybackActiveState(false);
        }
    }

    const viewHome = document.getElementById("view-home");
    const viewTv = document.getElementById("view-tv");
    const viewMovies = document.getElementById("view-movies");
    const viewSeries = document.getElementById("view-series");
    const viewAnimes = document.getElementById("view-animes");

    const tabHome = document.getElementById("nav-tab-home");
    const tabTv = document.getElementById("nav-tab-tv");
    const tabMovies = document.getElementById("nav-tab-movies");
    const tabSeries = document.getElementById("nav-tab-series");
    const tabAnimes = document.getElementById("nav-tab-animes");
    const tabSports = document.getElementById("nav-tab-sports");

    const allViews = [viewHome, viewTv, viewMovies, viewSeries, viewAnimes];
    allViews.forEach(v => {
        if (v) v.classList.add("hidden");
    });

    const allTabs = [tabHome, tabTv, tabMovies, tabSeries, tabAnimes, tabSports];
    allTabs.forEach(t => {
        if (t) t.classList.remove("active");
    });

    // Update Reactive Store
    store.setCurrentView(viewName);

    if (viewName === 'home') {
        if (viewHome) viewHome.classList.remove("hidden");
        if (tabHome) tabHome.classList.add("active");
        if (typeof viewHooks.onHome === 'function') viewHooks.onHome();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (viewName === 'movies') {
        if (viewMovies) viewMovies.classList.remove("hidden");
        if (tabMovies) tabMovies.classList.add("active");
        if (typeof viewHooks.onMovies === 'function') viewHooks.onMovies();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (viewName === 'series') {
        if (viewSeries) viewSeries.classList.remove("hidden");
        if (tabSeries) tabSeries.classList.add("active");
        if (typeof viewHooks.onSeries === 'function') viewHooks.onSeries();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (viewName === 'animes') {
        if (viewAnimes) viewAnimes.classList.remove("hidden");
        if (tabAnimes) tabAnimes.classList.add("active");
        if (typeof viewHooks.onAnimes === 'function') viewHooks.onAnimes();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (viewName === 'sports') {
        // Sports opens the TV view scrolled to the matches section or opens dedicated view
        if (viewHome) viewHome.classList.remove("hidden");
        if (tabSports) tabSports.classList.add("active");
        const matchesSection = document.getElementById("vasco-matches-section");
        if (matchesSection) {
            matchesSection.scrollIntoView({ behavior: 'smooth' });
        }
    } else {
        // Default: 'tv'
        if (viewTv) viewTv.classList.remove("hidden");
        if (tabTv) tabTv.classList.add("active");
        if (typeof viewHooks.onTv === 'function') viewHooks.onTv();
    }
}

export function setupSpaNavigation() {
    const tabHome = document.getElementById("nav-tab-home");
    const tabTv = document.getElementById("nav-tab-tv");
    const tabMovies = document.getElementById("nav-tab-movies");
    const tabSeries = document.getElementById("nav-tab-series");
    const tabAnimes = document.getElementById("nav-tab-animes");
    const tabSports = document.getElementById("nav-tab-sports");

    if (tabHome) tabHome.addEventListener("click", () => switchAppView('home'));
    if (tabTv) tabTv.addEventListener("click", () => switchAppView('tv'));
    if (tabMovies) tabMovies.addEventListener("click", () => switchAppView('movies'));
    if (tabSeries) tabSeries.addEventListener("click", () => switchAppView('series'));
    if (tabAnimes) tabAnimes.addEventListener("click", () => switchAppView('animes'));
    if (tabSports) tabSports.addEventListener("click", () => switchAppView('sports'));

    // Brand home logo buttons
    const brandHomeBtn = document.getElementById("brand-home");
    const mobileBrandHomeBtn = document.getElementById("mobile-brand-home");
    if (brandHomeBtn) brandHomeBtn.addEventListener("click", () => switchAppView('home'));
    if (mobileBrandHomeBtn) mobileBrandHomeBtn.addEventListener("click", () => switchAppView('home'));

    // Mobile drawer toggle buttons
    const btnToggleMenu = document.getElementById("btn-toggle-menu");
    const btnCloseMenu = document.getElementById("btn-close-menu");
    const sidebarBackdrop = document.getElementById("sidebar-backdrop");

    if (btnToggleMenu) btnToggleMenu.addEventListener("click", openMobileMenu);
    if (btnCloseMenu) btnCloseMenu.addEventListener("click", closeMobileMenu);
    if (sidebarBackdrop) sidebarBackdrop.addEventListener("click", closeMobileMenu);

    // Setup Home Portal Navigation Cards
    document.querySelectorAll("#view-home .home-portal-card").forEach(card => {
        const target = card.getAttribute("data-view-target");
        card.addEventListener("click", () => {
            if (target) switchAppView(target);
        });
    });
}

/**
 * TVZINHA ONLINE - Smart TV & Spatial Navigation Module (D-Pad / Remote Control)
 * Purely DOM-based spatial navigation with Euclidean 2D distance calculation
 */

import { store } from '../core/state.js';

export function setupTvRemoteNavigation() {
    function getFocusableElements() {
        const selector = [
            '#floating-nav-capsule .nav-capsule-item',
            '.home-portal-card',
            '.home-utility-card',
            '.continue-card',
            '.continue-watching-card',
            '#movies-search-input',
            '#series-search-input',
            '#animes-search-input',
            '#btn-hero-watch-movie',
            '.movie-poster-card',
            '#btn-close-movie-modal',
            '#btn-close-series-modal',
            '.btn-movie-server-pill',
            '.btn-series-server-pill',
            '.series-ep-card',
            '#series-season-select',
            '#btn-series-back',
            '#filter-pills .pill',
            '#btn-change-team',
            '#vasco-matches-grid .broadcast-pill.playable',
            '#channels-list .channel-item',
            '.btn-server-option',
            '.btn-player-action',
            '#search-input',
            '#btn-close-team-modal',
            '.team-select-option'
        ].join(', ');

        return Array.from(document.querySelectorAll(selector)).filter(el => {
            const rect = el.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0 && window.getComputedStyle(el).visibility !== 'hidden' && window.getComputedStyle(el).display !== 'none';
        });
    }

    function findBestDirectionalCandidate(currentEl, direction) {
        const currentRect = currentEl.getBoundingClientRect();
        const currentCenter = {
            x: currentRect.left + currentRect.width / 2,
            y: currentRect.top + currentRect.height / 2
        };

        const candidates = getFocusableElements().filter(el => el !== currentEl);
        let bestCandidate = null;
        let minDistance = Infinity;

        for (const candidate of candidates) {
            const rect = candidate.getBoundingClientRect();
            const center = {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };

            const dx = center.x - currentCenter.x;
            const dy = center.y - currentCenter.y;

            let isCandidateInDirection = false;
            switch (direction) {
                case 'up':
                    isCandidateInDirection = dy < -10 && Math.abs(dx) <= Math.abs(dy) * 1.75;
                    break;
                case 'down':
                    isCandidateInDirection = dy > 10 && Math.abs(dx) <= Math.abs(dy) * 1.75;
                    break;
                case 'left':
                    isCandidateInDirection = dx < -10 && Math.abs(dy) <= Math.abs(dx) * 1.75;
                    break;
                case 'right':
                    isCandidateInDirection = dx > 10 && Math.abs(dy) <= Math.abs(dx) * 1.75;
                    break;
            }

            if (isCandidateInDirection) {
                const distance = Math.hypot(dx, dy);
                if (distance < minDistance) {
                    minDistance = distance;
                    bestCandidate = candidate;
                }
            }
        }

        return bestCandidate;
    }

    window.addEventListener("keydown", (e) => {
        const activeModal = document.querySelector(".modal:not(.hidden), .movie-modal:not(.hidden), #team-select-modal:not(.hidden)");
        const tag = (document.activeElement && document.activeElement.tagName) || '';

        // Allow normal typing inside input elements
        if ((tag === 'INPUT' || tag === 'TEXTAREA') && !['ArrowUp', 'ArrowDown', 'Escape', 'Enter'].includes(e.key)) {
            return;
        }

        const key = e.key;

        if (key === 'Escape' || key === 'Back' || key === 'BrowserBack') {
            if (activeModal) {
                e.preventDefault();
                const closeBtn = activeModal.querySelector(".btn-close-modal, #btn-close-movie-modal, #btn-close-series-modal, #btn-close-team-modal");
                if (closeBtn) closeBtn.click();
                return;
            }
        }

        if (key === 'Enter') {
            const currentEl = document.activeElement;
            if (currentEl && currentEl !== document.body) {
                // If it's not a native link or button, trigger click
                if (currentEl.tagName !== 'BUTTON' && currentEl.tagName !== 'A') {
                    e.preventDefault();
                    currentEl.click();
                }
            }
            return;
        }

        const directions = {
            ArrowUp: 'up',
            ArrowDown: 'down',
            ArrowLeft: 'left',
            ArrowRight: 'right'
        };

        const dir = directions[key];
        if (dir) {
            const currentEl = document.activeElement;
            const focusables = getFocusableElements();
            if (focusables.length === 0) return;

            if (!currentEl || currentEl === document.body || !focusables.includes(currentEl)) {
                e.preventDefault();
                const currentView = store.currentView;
                if (currentView === 'movies') {
                    const defaultMovieEl = document.getElementById('btn-hero-watch-movie') || document.querySelector('.movie-poster-card') || focusables[0];
                    if (defaultMovieEl) defaultMovieEl.focus();
                } else if (currentView === 'tv') {
                    const defaultPlayerBtn = document.querySelector('.btn-server-option.active') || document.getElementById('btn-fullscreen-player') || focusables[0];
                    if (defaultPlayerBtn) defaultPlayerBtn.focus();
                } else {
                    const defaultHomeEl = document.querySelector('.nav-capsule-item.active') || focusables[0];
                    if (defaultHomeEl) defaultHomeEl.focus();
                }
                return;
            }

            const nextEl = findBestDirectionalCandidate(currentEl, dir);
            if (nextEl) {
                e.preventDefault();
                nextEl.focus();
                nextEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
            }
        }
    });

    console.log("[Remote] Smart TV D-Pad Spatial Navigation initialized.");
}

