function checkAdblockNoticeStatus() {
    setupAdblockModalHandlers();
    try {
        const rawTimestamp = localStorage.getItem(ABLOCK_STORAGE_KEY_LEGACY || ADBLOCK_STORAGE_KEY);
        if (!rawTimestamp) {
            setTimeout(() => openAdblockModal(), 600);
