import subprocess
import time
import json
import urllib.request
import asyncio
import os
import websockets

EDGE_PATH = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"

async def test_scroll():
    user_data = os.path.abspath("scratch/edge_scroll_profile")
    os.makedirs(user_data, exist_ok=True)

    proc = subprocess.Popen([
        EDGE_PATH,
        "--headless=new",
        "--remote-debugging-port=9226",
        "--remote-allow-origins=*",
        f"--user-data-dir={user_data}",
        "--disable-gpu",
        "--window-size=1280,800",
        "--no-first-run",
        "http://localhost:8787"
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    try:
        await asyncio.sleep(2)
        req = urllib.request.urlopen("http://127.0.0.1:9226/json")
        targets = json.loads(req.read().decode('utf-8'))
        page_target = next((t for t in targets if t.get("type") == "page" and "localhost:8787" in t.get("url", "")), None)
        assert page_target, "No page target found"

        async with websockets.connect(page_target["webSocketDebuggerUrl"]) as ws:
            await ws.send(json.dumps({"id": 1, "method": "Runtime.enable"}))

            cmd_id = 10
            async def evaluate(expr):
                nonlocal cmd_id
                cmd_id += 1
                await ws.send(json.dumps({
                    "id": cmd_id,
                    "method": "Runtime.evaluate",
                    "params": {"expression": expr, "returnByValue": True, "awaitPromise": True}
                }))
                while True:
                    msg = await ws.recv()
                    data = json.loads(msg)
                    if data.get("id") == cmd_id:
                        res = data.get("result", {})
                        if "exceptionDetails" in res:
                            exc = res["exceptionDetails"]
                            return {"error": exc.get("exception", {}).get("description", exc.get("text"))}
                        return res.get("result", {}).get("value")

            # Check overflow styles and scroll heights
            info = await evaluate("""
                (() => {
                    const html = document.documentElement;
                    const body = document.body;
                    const viewHome = document.getElementById('view-home');

                    return {
                        htmlStyles: {
                            overflow: window.getComputedStyle(html).overflow,
                            overflowY: window.getComputedStyle(html).overflowY,
                            height: window.getComputedStyle(html).height,
                            scrollHeight: html.scrollHeight,
                            clientHeight: html.clientHeight
                        },
                        bodyStyles: {
                            overflow: window.getComputedStyle(body).overflow,
                            overflowY: window.getComputedStyle(body).overflowY,
                            height: window.getComputedStyle(body).height,
                            scrollHeight: body.scrollHeight,
                            clientHeight: body.clientHeight,
                            styleOverflow: body.style.overflow
                        },
                        viewHomeStyles: viewHome ? {
                            height: window.getComputedStyle(viewHome).height,
                            scrollHeight: viewHome.scrollHeight,
                            clientHeight: viewHome.clientHeight,
                            overflow: window.getComputedStyle(viewHome).overflow
                        } : null,
                        windowInnerHeight: window.innerHeight,
                        canScroll: html.scrollHeight > window.innerHeight || body.scrollHeight > window.innerHeight
                    };
                })()
            """)
            print("INITIAL SCROLL INFO:")
            print(json.dumps(info, indent=2))

            # Try scrolling by 200px
            scroll_test = await evaluate("""
                (() => {
                    window.scrollTo(0, 300);
                    return {
                        scrollY: window.scrollY,
                        pageYOffset: window.pageYOffset,
                        htmlScrollTop: document.documentElement.scrollTop,
                        bodyScrollTop: document.body.scrollTop
                    };
                })()
            """)
            print("AFTER WINDOW.SCROLLTO(0, 300):")
            print(json.dumps(scroll_test, indent=2))

    finally:
        proc.terminate()
        proc.wait()

if __name__ == "__main__":
    asyncio.run(test_scroll())

