    const modal = document.getElementById("adblock-modal");
    if (modal) {
        modal.classList.add("hidden");
        modal.style.display = "none";
        document.body.style.overflow = "";
    }
    try {
        localStorage.setItem(ADBLOCK_STORAGE_KEY, Date.now().toString());
    } catch (e) {}
}

